\begin{theorem}[Commutativity of~$G$]\label{thm:com-main}
  Let $(\psi, A, B, L)$ be an $(\eps, \delta, \gamma)$-good symmetric strategy for the $(m,q,d)$ low individual degree test.
  Let $\{G^x\}_{x \in \F_q}$ denote a set of projective sub-measurements in $\polysub{m}{q}{d}$ with the following properties:
  \begin{enumerate}
  \item (Consistency with~$A$): \label{item:commuting-consistency} On average over $(\bu, \bx) \sim \F_q^{m+1}$,
	  \begin{equation*}
	  A^{u, x}_a \otimes I \simeq_{\zeta} I \otimes G^x_{[g(u)=a]}.
	  \end{equation*}
  \item (Strong self-consistency): \label{item:commuting-self-consistency} On average over~$\bx \sim \F_q$,
  	\begin{equation*}
		G^x_g \otimes I \approx_{\zeta} I \otimes G^x_g.
	\end{equation*}
  \item (Boundedness): \label{item:commuting-boundedness} There exists a positive-semidefinite matrix $Z^x$ for each $x \in \F_q$ such that
  	\begin{equation*}
		\E_{\bx} \bra{\psi} (I-G^{\bx})\otimes Z^{\bx} \ket{\psi} \leq \zeta
	\end{equation*}
	and for each $x \in \F_q$ and $g \in \polyfunc{m}{q}{d}$,
	\begin{equation*}
	Z^x \geq \left(\E_{\bu} A^{\bu, x}_{g(\bu)}\right).
	\end{equation*}
  \end{enumerate}
  Let
  \begin{equation*}
  \nu = 30m \cdot \left(\gamma^{1/4}+ \zeta^{1/4} + (d/q)^{1/4}  \right).
  \end{equation*}
  Then on average over independent and uniformly random $(\bu,\bx), (\bv,\by) \sim \F_q^{m+1}$,
  \begin{equation*}
    G^{x}_{g} G^{y}_h \ot I \approx_{\nu} G^y_h G^x_g \ot I
  \end{equation*}
\end{theorem}

\begin{proof}
\begin{lemma}[Commutativity of~$G$ after evaluation]
  \label{lem:comm-data-processed-g}
  Let $(\psi, A, B, L)$ be an $(\eps, \delta, \gamma)$-good symmetric strategy for the $(m+1,q,d)$ low individual degree test.
  Let $\{G^x\} \in \polysub{m}{q}{d}$ be a collection of projective sub-measurements indexed by $x \in \F_q$ with the following properties:
  \begin{enumerate}
  \item (Consistency with~$A$): \label{item:data-processed-consistency} On average over $(\bu, \bx) \sim \F_q^{m+1}$,
	  \begin{equation*}
	  A^{u, x}_a \otimes I \simeq_{\zeta} I \otimes G^x_{[g(u)=a]}.
	  \end{equation*}
  \item (Strong self-consistency): \label{item:data-processed-self-consistency} On average over~$\bx \sim \F_q$,
  	\begin{equation*}
		G^x_g \otimes I \approx_{\zeta} I \otimes G^x_g.
	\end{equation*}
  \item (Boundedness): \label{item:data-processed-boundedness} There exists a positive-semidefinite matrix $Z^x$ for each $x \in \F_q$ such that
  	\begin{equation*}
		\E_{\bx} \bra{\psi} (I-G^{\bx})\otimes Z^{\bx} \ket{\psi} \leq \zeta
	\end{equation*}
	and for each $x \in \F_q$ and $g \in \polyfunc{m}{q}{d}$,
	\begin{equation*}
	 Z^x \geq \left(\E_{\bu} A^{\bu, x}_{g(\bu)}\right).
	\end{equation*}
  \end{enumerate}
  Let
  \begin{equation*}
  \nu = 48 m \cdot (\gamma^{1/2} + \zeta^{1/2}).
  \end{equation*}
  Then on average over independent and uniformly random $(\bu,\bx), (\bv,\by) \sim \F_q^{m+1}$,
  \begin{equation*}
    G^x_{[g(u) = a]} G^y_{[h(v) = b]} \ot I \approx_{\nu} G^y_{[h(v) = b]}
    G^x_{[g(u) = a]} \ot I.
  \end{equation*}
\end{lemma}

We now prove the full self-improvement theorem, i.e.\ \Cref{thm:self-improvement-in-induction-section}.
To do so, we will apply the orthonormalization lemma \Cref{thm:orthonormalization}
to the output of \Cref{lem:self-improvement-helper} and argue that it maintains the four properties of~$H$.

\begin{theorem}[Self-improvement; \Cref{thm:self-improvement-in-induction-section} restated]\label{thm:self-improvement}
Let $G \in \polymeas{m}{q}{d}$ be a measurement with the following properties:
\begin{enumerate}

  \item (Consistency with~$A$): \label{item:self-improvement-projective-G-consistency} On average over $\bu \sim \F_q^{m}$,
	  \begin{equation*}
	  A^{u}_a \otimes I \simeq_{\nu} I \otimes G_{[g(u)=a]}.
	  \end{equation*}
	  \end{enumerate}
Let
\begin{equation*}
  (1 / (params.m : Error)) *
    ∑ j : Fin params.m,
      bipartiteConsError strategy.state
        (uniformDistribution (RestrictedDiagonalSample params j))
        (diagonalPointAnswerFamily strategy j)
        (diagonalLineAnswerFamily strategy j)

/-- Goodness data for an answer-valued symmetric strategy. -/
structure IsGood {params : Parameters}
    {ι : Type*} [Fintype ι] [DecidableEq ι]
    [FieldModel params.q]
    (strategy : AnswerSymStrat params ι)
    (eps delta gamma : Error) : Prop where
  /-- The axis-parallel test fails with probability at most `eps`. -/
  axisParallelTest : strategy.axisParallelFailureProbability ≤ eps
  /-- The self-consistency test fails with probability at most `delta`. -/
  selfConsistencyTest : strategy.selfConsistencyFailureProbability ≤ delta
  /-- The diagonal-line test fails with probability at most `gamma`. -/
  diagonalLineTest : strategy.diagonalFailureProbability ≤ gamma

end AnswerSymStrat

/-- Paper-faithful two-space projective strategy data.

This matches the paper's `def:general-projective-strategy`
(`test_definition.tex`, lines 98--115): Alice's and Bob's measurements act on
separate local carriers `ιA` and `ιB`, and the bipartite state lives on
`ιA × ιB` without a built-in swap symmetry.

structure ProjStrat (params : Parameters) [FieldModel params.q]
    (ιA : Type*) [Fintype ιA] [DecidableEq ιA]
    (ιB : Type*) [Fintype ιB] [DecidableEq ιB] where
  /-- Bipartite state on the tensor product of Alice's and Bob's local carriers. -/
  state : QuantumState (ιA × ιB)
  /-- The bipartite state's density operator is trace-normalized. -/
  isNormalized : state.IsNormalized
  /-- Alice's point-measurement family, acting on `ιA`. -/
  pointMeasurementA : IdxProjMeas (Point params) (Fq params) ιA
  /-- Alice's axis-parallel-line measurement family, acting on `ιA`. -/
  axisParallelMeasurementA :
    IdxProjMeas (AxisParallelLine params) (AxisLinePolynomial params) ιA
  /-- Alice's axis-parallel measurement is covariant under line rebasing. -/
  axisParallelReparamInvariantA :
    AxisParallelMeasurementReparamInvariant params axisParallelMeasurementA
  /-- Alice's diagonal-line measurement family, acting on `ιA`. -/
  diagonalMeasurementA :
    IdxProjMeas (DiagonalLine params) (DiagonalLinePolynomial params) ιA
  /-- Alice's diagonal measurement is covariant under line rebasing. -/
  diagonalReparamInvariantA :
    DiagonalMeasurementReparamInvariant params diagonalMeasurementA
  /-- Bob's point-measurement family, acting on `ιB`. -/
  pointMeasurementB : IdxProjMeas (Point params) (Fq params) ιB
  /-- Bob's axis-parallel-line measurement family, acting on `ιB`. -/
  axisParallelMeasurementB :
    IdxProjMeas (AxisParallelLine params) (AxisLinePolynomial params) ιB
  /-- Bob's axis-parallel measurement is covariant under line rebasing. -/
  axisParallelReparamInvariantB :
    AxisParallelMeasurementReparamInvariant params axisParallelMeasurementB
  /-- Bob's diagonal-line measurement family, acting on `ιB`. -/
  diagonalMeasurementB :
    IdxProjMeas (DiagonalLine params) (DiagonalLinePolynomial params) ιB
  /-- Bob's diagonal measurement is covariant under line rebasing. -/
  diagonalReparamInvariantB :
    DiagonalMeasurementReparamInvariant params diagonalMeasurementB

end MIPStarRE.LDT
